 "content": "from collections import deque


def transform(grid):
    """Recolor the largest and smallest 4-connected zero regions."""
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])
    seen = set()
    components = []

    for r in range(height):
        for c in range(width):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            queue = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while queue:
                x, y = queue.popleft()
                cells.append((x, y))
                for nx, ny in ((x - 1, y), (x + 1, y), (x, y - 1), (x, y + 1)):
                    if (0 <= nx < height and 0 <= ny < width
                            and grid[nx][ny] == 0 and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        queue.append((nx, ny))
            components.append(cells)

    if len(components) >= 2:
        smallest = min(components, key=len)
        largest = max(components, key=len)
        for r, c in smallest:
            out[r][c] = 7
        for r, c in largest:
            out[r][c] = 8
    return out


if __name__ == "__main__":
    import json
    import sys
    print(json.dumps(transform(json.loads(sys.stdin.read()))))
